-- Configure RLS policies for daily_production so only the creator can delete
DO $$
BEGIN
  IF to_regclass('public.daily_production') IS NOT NULL THEN
    -- Enable RLS
    EXECUTE 'ALTER TABLE public.daily_production ENABLE ROW LEVEL SECURITY';

    -- Allow selecting all entries (for analytics and histórico)
    IF NOT EXISTS (
      SELECT 1 FROM pg_policies 
      WHERE schemaname = 'public' AND tablename = 'daily_production' AND policyname = 'All users can view daily production'
    ) THEN
      EXECUTE 'CREATE POLICY "All users can view daily production" ON public.daily_production FOR SELECT USING (true)';
    END IF;

    -- Only allow inserts where created_by matches auth.uid()
    IF NOT EXISTS (
      SELECT 1 FROM pg_policies 
      WHERE schemaname = 'public' AND tablename = 'daily_production' AND policyname = 'Users can insert their own daily production'
    ) THEN
      EXECUTE 'CREATE POLICY "Users can insert their own daily production" ON public.daily_production FOR INSERT WITH CHECK (auth.uid() = created_by)';
    END IF;

    -- Only allow updates by the creator
    IF NOT EXISTS (
      SELECT 1 FROM pg_policies 
      WHERE schemaname = 'public' AND tablename = 'daily_production' AND policyname = 'Users can update their own daily production'
    ) THEN
      EXECUTE 'CREATE POLICY "Users can update their own daily production" ON public.daily_production FOR UPDATE USING (auth.uid() = created_by)';
    END IF;

    -- Only allow deletes by the creator
    IF NOT EXISTS (
      SELECT 1 FROM pg_policies 
      WHERE schemaname = 'public' AND tablename = 'daily_production' AND policyname = 'Users can delete their own daily production'
    ) THEN
      EXECUTE 'CREATE POLICY "Users can delete their own daily production" ON public.daily_production FOR DELETE USING (auth.uid() = created_by)';
    END IF;
  END IF;
END$$;

